class FindSumPairs { private final int[] nums1,nums2;private final Map<Integer,Integer> frequency=new HashMap<>();public FindSumPairs(int[] nums1,int[] nums2){this.nums1=nums1;this.nums2=nums2;for(int value:nums2)frequency.merge(value,1,Integer::sum);}public void add(int index,int val){frequency.merge(nums2[index],-1,Integer::sum);nums2[index]+=val;frequency.merge(nums2[index],1,Integer::sum);}public int count(int tot){int answer=0;for(int value:nums1)answer+=frequency.getOrDefault(tot-value,0);return answer;} }
